SELECT
platform AS name,
COUNT(id) AS value
FROM sys_login_session
WHERE 1 = 1

    AND last_access_year = #{year}


    AND last_access_month = #{month}


    AND last_access_day = #{day}

GROUP BY client_name

SELECT COUNT(*) from sys_login_session where active = 1

    and created_at >= #{startTime}


    and created_at < #{endTime}
